namespace sv_e47a218788894684a6f8935d77c74ca8.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Because Blazor Server scopes DI per circuit, each user gets their own instance.
/// </summary>
public sealed class WarehouseStateService
{
    private string _currentWarehouseId = "WH-1";

    public string CurrentWarehouseId => _currentWarehouseId;

    /// <summary>Raised whenever the selected warehouse changes.</summary>
    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-1", "Warehouse A — Downtown"),
        ("WH-2", "Warehouse B — Airport"),
        ("WH-3", "Warehouse C — Harbor"),
    ];
}

namespace sv_e47a218788894684a6f8935d77c74ca8.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all
/// subscribed components when new data arrives.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _latestCount;
    private string? _latestWarehouseId;

    /// <summary>The most recently fetched low-stock count.</summary>
    public int LatestLowStockCount => _latestCount;

    /// <summary>Raised after new alert data has been fetched.</summary>
    public event Action? OnAlertDataChanged;

    /// <summary>Simulates a database query returning low-stock item count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        int count = _random.Next(0, 16); // 0–15 inclusive
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches new data and notifies all subscribers.
    /// Called by the polling component; every subscribed component will update.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        _latestCount = await GetLowStockCountAsync(warehouseId);
        _latestWarehouseId = warehouseId;
        OnAlertDataChanged?.Invoke();
    }

    public void Dispose()
    {
        // Clear delegates to prevent leaks if service outlives components.
        OnAlertDataChanged = null;
    }
}

