@using sv_e47a218788894684a6f8935d77c74ca8.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-5">
            <strong>@CurrentWarehouseName</strong>
            <span class="text-muted">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            @if (AlertService.LatestLowStockCount > 0)
            {
                <span class="badge bg-danger ms-2">@AlertService.LatestLowStockCount items</span>
            }
            else
            {
                <span class="badge bg-success ms-2">All stocked</span>
            }
        </h5>
        <p class="card-text text-muted">
            Polling every 10 seconds. Last check: @_lastPollTime?.ToString("HH:mm:ss") ?? "—"
        </p>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private DateTime? _lastPollTime;

    private string CurrentWarehouseName =>
        WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
        ?? WarehouseState.CurrentWarehouseId;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertDataChanged += OnAlertDataChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Do an immediate fetch, then start the 10-second polling loop
            await PollOnceAsync();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await PollOnceAsync();
            }
        }
        catch (OperationCanceledException) { /* expected on dispose / warehouse change */ }
    }

    private async Task PollOnceAsync()
    {
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        _lastPollTime = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse and fetch immediately
        InvokeAsync(async () =>
        {
            StartPolling();
            await PollOnceAsync();
        });
    }

    private void OnAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
    }
}

